// Flat lookup: team name -> flag emoji.
export const FLAG_BY_TEAM = Object.values(TEAMS)
  .flat()
  .reduce((acc, t) => {
    acc[t.name] = t.flag
    return acc
  }, {})

// Sorted list of all team names (for the team filter).
export const ALL_TEAMS = Object.values(TEAMS)
  .flat()
  .map((t) => t.name)
  .sort((a, b) => a.localeCompare(b))
